import React from 'react';

const DiscussionDetailsPage = () => {
  return (
    <div>
      <h1 className="text-4xl font-bold mb-8">Discussion Details</h1>
      <div className="bg-white p-8 rounded-lg shadow-md">
        <p className="text-gray-600 text-center">Discussion details will be displayed here</p>
      </div>
    </div>
  );
};

export default DiscussionDetailsPage;
